import{_ as t,o as i,c as a,a2 as o}from"./chunks/framework.DaGSOal_.js";const p=JSON.parse('{"title":"Contributing","description":"Propose corrections and improvements to Deblx documentation through GitHub.","frontmatter":{"title":"Contributing","description":"Propose corrections and improvements to Deblx documentation through GitHub."},"headers":[],"relativePath":"contributing.md","filePath":"contributing.md","lastUpdated":1794006476000}'),n={name:"contributing.md"};function r(l,e,c,s,h,u){return i(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="contributing-to-the-documentation" tabindex="-1">Contributing to the Documentation <a class="header-anchor" href="#contributing-to-the-documentation" aria-label="Permalink to &quot;Contributing to the Documentation&quot;">​</a></h1><p>The documentation is maintained in the public <a href="https://github.com/deblx/docs" target="_blank" rel="noreferrer">deblx/docs</a> repository. Product instructions are written in Markdown.</p><h2 id="suggest-a-change" tabindex="-1">Suggest a Change <a class="header-anchor" href="#suggest-a-change" aria-label="Permalink to &quot;Suggest a Change&quot;">​</a></h2><ol><li>Open the documentation article you want to improve.</li><li>Select <strong>Edit this page on GitHub</strong> near the end of the article.</li><li>Edit the Markdown source in GitHub.</li><li>Propose the changes through a pull request.</li><li>Explain what changed and which Unreal Engine or plugin version the correction applies to.</li></ol><p>If you prefer not to edit GitHub files, contact the <a href="https://deblx.com/help" target="_blank" rel="noreferrer">Deblx Help Center</a>.</p><h2 id="documentation-guidelines" tabindex="-1">Documentation Guidelines <a class="header-anchor" href="#documentation-guidelines" aria-label="Permalink to &quot;Documentation Guidelines&quot;">​</a></h2><ul><li>Use concise, practical steps and correct menu names.</li><li>Keep product names, version requirements and file paths accurate.</li><li>Link to relevant product guides rather than duplicating instructions.</li><li>Avoid unverified claims about compatibility, performance or privacy.</li><li>Remove personal data, tokens and private project paths from logs or screenshots.</li><li>Place screenshots in the repository only when publication is permitted.</li></ul><h2 id="review-and-publishing" tabindex="-1">Review and Publishing <a class="header-anchor" href="#review-and-publishing" aria-label="Permalink to &quot;Review and Publishing&quot;">​</a></h2><p>Proposed changes are reviewed before being merged into the main branch. The documentation preview updates automatically from the migration branch. Once the migration is complete, changes merged into <code>main</code> will build and publish automatically through GitHub Actions.</p><h2 id="where-to-find-sources" tabindex="-1">Where to Find Sources <a class="header-anchor" href="#where-to-find-sources" aria-label="Permalink to &quot;Where to Find Sources&quot;">​</a></h2><ul><li><a href="/compatibility">Unreal Engine compatibility</a></li><li><a href="/workflows">Practical workflows</a></li><li><a href="https://changelog.deblx.com" target="_blank" rel="noreferrer">Deblx Changelog</a></li><li><a href="https://www.fab.com/de/sellers/Deblx" target="_blank" rel="noreferrer">Fab Marketplace</a></li></ul>',11)])])}const g=t(n,[["render",r]]);export{p as __pageData,g as default};
